import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Field, GraphQLModule, Int, ObjectType, Query, Resolver } from "@nestjs/graphql"

@ObjectType()
class Book {
    @Field(() => Int) id: number
    @Field() title: string
    @Field() author: string
}

@Resolver(() => Book)
class BooksResolver {
    private data = [
        { id: 1, title: "O'tkan kunlar", author: "Abdulla Qodiriy" },
        { id: 2, title: "Sarob", author: "Abdulla Qahhor" },
    ]
    @Query(() => [Book]) books() { return this.data }
}

@Module({
    imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })],
    providers: [BooksResolver],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ books { id title } }" })
    await http.close()
}
main()

