import { Module, NotFoundException } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, Int, ObjectType, Query, Resolver } from "@nestjs/graphql"

@ObjectType()
class Movie {
    @Field(() => Int) id: number
    @Field() title: string
    @Field(() => Int) year: number
}

const movies = [{ id: 1, title: "Shum bola", year: 1977 }, { id: 2, title: "Mahallada duv-duv gap", year: 1960 }]

@Resolver(() => Movie)
class MoviesResolver {
    @Query(() => Movie)
    movie(@Args("id", { type: () => Int }) id: number) {
        const m = movies.find(x => x.id === id)
        if (!m) throw new NotFoundException(`Film #${id} topilmadi`)
        return m
    }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [MoviesResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ movie(id: 1) { title year } }" })
    const res = await fetch((await http.app.getUrl()) + "/graphql", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: "{ movie(id: 9) { title } }" }),
    })
    const body = await res.json()
    console.log("xato:", body.errors[0].message, "| kod:", body.errors[0].extensions.code)
    await http.close()
}
main()

