import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, Int, ObjectType, Query, registerEnumType, Resolver } from "@nestjs/graphql"

enum OrderStatus { NEW = "NEW", PAID = "PAID", SHIPPED = "SHIPPED" }
registerEnumType(OrderStatus, { name: "OrderStatus", description: "Buyurtma holati" })

@ObjectType()
class Order {
    @Field(() => Int) id: number
    @Field(() => OrderStatus) status: OrderStatus
}

const orders = [{ id: 1, status: OrderStatus.NEW }, { id: 2, status: OrderStatus.PAID }, { id: 3, status: OrderStatus.PAID }]

@Resolver(() => Order)
class OrdersResolver {
    @Query(() => [Order])
    orders(@Args("status", { type: () => OrderStatus }) status: OrderStatus) { return orders.filter(o => o.status === status) }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [OrdersResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ orders(status: PAID) { id status } }" })
    await http.close()
}
main()

