import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, InputType, Int, Mutation, ObjectType, Query, Resolver } from "@nestjs/graphql"

@InputType() class NewDishInput {
    @Field() name!: string
    @Field(() => Int) price!: number
}

@ObjectType() class Dish {
    @Field(() => Int) id!: number
    @Field() name!: string
    @Field(() => Int) price!: number
}

const dishes: Dish[] = []
@Resolver()
class DishesResolver {
    @Query(() => Int) count() { return dishes.length }
    @Mutation(() => Dish) addDish(@Args("input") input: NewDishInput) {
        const dish = { id: dishes.length + 1, ...input }
        dishes.push(dish)
        return dish
    }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [DishesResolver] })
