import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Field, GraphQLModule, ObjectType, Query, Resolver } from "@nestjs/graphql"
import { ASTVisitor, GraphQLError, ValidationContext } from "graphql"

function depthLimit(max: number) {
    return (ctx: ValidationContext): ASTVisitor => {
        let depth = 0, reported = false
        return {
            Field: {
                enter(node) {
                    depth++
                    if (depth > max && !reported) {
                        reported = true
                        ctx.reportError(new GraphQLError(`So'rov juda chuqur: ${depth} > ${max}`, { nodes: [node] }))
                    }
                },
                leave() { depth-- },
            },
        }
    }
}

@ObjectType() class Category {
    @Field() name!: string
    @Field(() => Category, { nullable: true }) parent?: Category
}

const tree = { name: "Somsa", parent: { name: "Pishiriqlar", parent: { name: "Taomlar", parent: { name: "Menyu" } } } }
@Resolver()
class CategoryResolver { @Query(() => Category) category() { return tree } }

@Module({
    imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true, includeStacktraceInErrorResponses: false, validationRules: [depthLimit(3)] })],
    providers: [CategoryResolver],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ category { parent { name } } }" })
    await http.post("/graphql", { query: "{ category { parent { parent { parent { name } } } } }" })
    await http.close()
}
