import { Module, Scope, Injectable } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Field, GraphQLModule, Int, ObjectType, Parent, Query, ResolveField, Resolver } from "@nestjs/graphql"

const authorsDb = new Map([[1, "Qodiriy"], [2, "Cho'lpon"]])
let dbCalls = 0

// Oddiy batch loader: bir "tick" davomida kelgan ID'larni bitta so'rovga birlashtiradi
@Injectable({ scope: Scope.REQUEST })
class AuthorLoader {
    private queue: { id: number; resolve: (v: string) => void }[] = []
    load(id: number) {
        return new Promise<string>(resolve => {
            this.queue.push({ id, resolve })
            if (this.queue.length === 1) process.nextTick(() => this.flush())
        })
    }
    private flush() {
        const batch = this.queue.splice(0)
        dbCalls++
        const ids = [...new Set(batch.map(b => b.id))]
        console.log(`DB so'rovi #${dbCalls}: WHERE id IN (${ids.join(", ")})`)
        batch.forEach(b => b.resolve(authorsDb.get(b.id)!))
    }
}

@ObjectType() class Book { @Field() title: string; authorId: number }

@Resolver(() => Book)
class BooksResolver {
    constructor(private readonly loader: AuthorLoader) {}
    @Query(() => [Book]) books() {
        return [{ title: "O'tkan kunlar", authorId: 1 }, { title: "Mehrobdan chayon", authorId: 1 }, { title: "Kecha va kunduz", authorId: 2 }]
    }
    @ResolveField(() => String) author(@Parent() b: Book) { return this.loader.load(b.authorId) }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [BooksResolver, AuthorLoader] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ books { title author } }" })
    await http.close()
}
main()

