import { Args, Field, GraphQLModule, InputType, Mutation, ObjectType, Query, Resolver } from "@nestjs/graphql"

@InputType() class SignupInput { @Field() email: string; @Field() password: string }
@ObjectType() class SignupPayload {
    @Field() ok: boolean
    @Field(() => [String]) errors: string[]
    @Field({ nullable: true }) userId?: string
}

@Resolver()
class AuthResolver {
    @Query(() => String) ping() { return "pong" }
    @Mutation(() => SignupPayload) signup(@Args("input") input: SignupInput): SignupPayload {
        const errors = [
            ...(!input.email.includes("@") ? ["email noto'g'ri"] : []),
            ...(input.password.length < 8 ? ["parol juda qisqa"] : []),
        ]
        return errors.length ? { ok: false, errors } : { ok: true, errors: [], userId: "u-1" }
    }
}
