import { CallHandler, ExecutionContext, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { GqlExecutionContext, GraphQLModule, Query, Resolver } from "@nestjs/graphql"
import { tap } from "rxjs"

@Injectable()
class GqlLogInterceptor implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const info = GqlExecutionContext.create(ctx).getInfo()
        console.log(`  → ${info.parentType.name}.${info.fieldName}`)
        return next.handle().pipe(tap(() => console.log(`  ← ${info.fieldName} tayyor`)))
