    name: "Money",
    description: "So'm; server ichida tiyinda saqlanadi",
    serialize: v => `${(Number(v) / 100).toFixed(2)} so'm`,
    parseValue: v => Math.round(Number(v) * 100),
    parseLiteral: ast => (ast.kind === Kind.INT || ast.kind === Kind.FLOAT ? Math.round(Number(ast.value) * 100) : null),
})

