import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Context, Field, GraphQLModule, Int, ObjectType, Parent, Query, ResolveField, Resolver } from "@nestjs/graphql"

@ObjectType() class Author { @Field() name!: string }
@ObjectType() class Post { @Field() title!: string; @Field(() => Author) author!: Author; authorId!: number }

let dbCalls = 0
const authors: Record<number, string> = { 1: "Ali", 2: "Vali" }

interface Ctx { cache: Map<number, Promise<Author>> }

@Resolver(() => Post)
class PostsResolver {
    @Query(() => [Post]) posts() { return [1, 2, 1, 1, 2].map((authorId, i) => ({ title: `Post ${i + 1}`, authorId })) }

    @ResolveField(() => Author) author(@Parent() post: Post, @Context() ctx: Ctx) {
        let p = ctx.cache.get(post.authorId)
        if (!p) {
            p = Promise.resolve().then(() => { dbCalls++; return { name: authors[post.authorId] } })
            ctx.cache.set(post.authorId, p)
        }
        return p
    }
}

@Module({
    imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true, context: (): Ctx => ({ cache: new Map() }) })],
    providers: [PostsResolver],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "{ posts { title author { name } } }" })
    console.log("bazaga murojaat (5 post, 2 muallif):", dbCalls)
    await http.post("/graphql", { query: "{ posts { author { name } } }" })
    console.log("ikkinchi so'rovdan keyin:", dbCalls, "(kesh har so'rovda yangi)")
    await http.close()
}
main()

