import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, Int, Mutation, ObjectType, Parent, Query, ResolveField, Resolver } from "@nestjs/graphql"

@ObjectType() class Author { @Field(() => Int) id!: number; @Field() name!: string }
@ObjectType() class Post { @Field(() => Int) id!: number; @Field() title!: string; @Field(() => Author) author!: Author; authorId!: number }

const authors = [{ id: 1, name: "Ali" }, { id: 2, name: "Vali" }]
const posts: Post[] = []

@Resolver(() => Post)
class PostsResolver {
    @Query(() => Int) postsCount() { return posts.length }

    @Mutation(() => Post) createPost(@Args("title") title: string, @Args("authorId", { type: () => Int }) authorId: number) {
        const post = { id: posts.length + 1, title, authorId } as Post
        posts.push(post)
        return post
    }

    @ResolveField(() => Author) author(@Parent() post: Post) { return authors.find(a => a.id === post.authorId) }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [PostsResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: `mutation { createPost(title: "Somsa sirlari", authorId: 2) { id title author { name } } }` })
    await http.close()
}
main()

