import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Context, GraphQLModule, Query, Resolver } from "@nestjs/graphql"

const cache = new Map<string, string>()

@Resolver()
class MenuResolver {
    @Query(() => [String]) menu(@Context("res") res: { setHeader(name: string, value: string): void }) {
        res.setHeader("x-cache", cache.has("menu") ? "HIT" : "MISS")
        if (!cache.has("menu")) cache.set("menu", "osh,manti")
        return cache.get("menu")!.split(",")
    }
}

@Module({
    imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true, context: ({ req, res }: { req: unknown; res: unknown }) => ({ req, res }) })],
    providers: [MenuResolver],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    for (let i = 0; i < 2; i++) {
        const r = await http.post("/graphql", { query: "{ menu }" })
        console.log("  x-cache:", r.headers.get("x-cache"))
    }
    await http.close()
}
main()

