import { Module } from "@nestjs/common"
import { ApolloDriver, ApolloDriverConfig } from "@nestjs/apollo"
import { Args, Field, GraphQLModule, InputType, Int, Mutation, ObjectType, PartialType, Query, Resolver } from "@nestjs/graphql"

@InputType() class CreateDishInput {
    @Field() name!: string
    @Field(() => Int) price!: number
    @Field() category!: string
}
@InputType() class UpdateDishInput extends PartialType(CreateDishInput) {}

@ObjectType() class Dish {
    @Field(() => Int) id!: number
    @Field() name!: string
    @Field(() => Int) price!: number
    @Field() category!: string
}

const dishes: Dish[] = [{ id: 1, name: "Osh", price: 35000, category: "asosiy" }]

@Resolver()
class DishesResolver {
    @Query(() => [Dish]) dishes() { return dishes }
    @Mutation(() => Dish) updateDish(@Args("id", { type: () => Int }) id: number, @Args("input") input: UpdateDishInput) {
        const dish = dishes.find(d => d.id === id)!
        return Object.assign(dish, input)
    }
}

@Module({ imports: [GraphQLModule.forRoot<ApolloDriverConfig>({ driver: ApolloDriver, autoSchemaFile: true })], providers: [DishesResolver] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/graphql", { query: "mutation { updateDish(id: 1, input: { price: 38000 }) { name price category } }" })
    await http.close()
}
main()
